// The anti-pattern — trivially recoverable with jadx or strings:
object ApiKeys {
    const val privateKey = "sk_live_1234abcd"   // leaks the moment the APK ships
}

// The working pattern: a short-lived credential issued by your backend.
suspend fun obtainSession(authCode: String): SessionCredential {
    val resp = api.exchangeCodeForToken(authCode)
    return SessionCredential(
        accessToken = resp.accessToken,    // ~30 min lifetime
        refreshToken = resp.refreshToken,  // revocable server-side
    )
}

