// After R8 (illustrative): class a { String a() { return "https://api.example.com/v3/token"; } }
// The identifiers are renamed; the string and the HTTPS call survive verbatim.

// String hiding is not protection either — Base64 is one line of work:
val apiKey = String(Base64.decode("c2stbGl2ZS0xMjM0NTY=", Base64.DEFAULT))
// Same secret, marginally harder to grep. Obfuscation delays; it does not hide.

fun secure(activity: Activity) {
    activity.window.setFlags(
        WindowManager.LayoutParams.FLAG_SECURE,
        WindowManager.LayoutParams.FLAG_SECURE
    )
}

// Compose: toggle the flag per screen instead of app-wide.
val window = (LocalView.current.context as? Activity)?.window
SideEffect {
    if (screenIsSensitive) {
        window?.addFlags(WindowManager.LayoutParams.FLAG_SECURE)
    } else {
        window?.clearFlags(WindowManager.LayoutParams.FLAG_SECURE)
    }
}

// Clipboard hygiene: drop anything sensitive when the app loses focus.
override fun onPause() {
    clipboard.clearPrimaryClip()
    super.onPause()
}

val pickVisualMedia = rememberLauncherForActivityResult(
    ActivityResultContracts.PickVisualMedia()
) { uri: Uri? ->
    uri?.let(::attachPhoto)   // content:// grant, not a permission
}

fun onPickPhoto() {
    pickVisualMedia.launch(
        PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly)
    )
}

class SecurityReviewUnitTest {
    private val blockedFragments = listOf(
        "cleartextTrafficPermitted=\"true\"",
        "usesCleartextTraffic=\"true\"",
        "android:debuggable=\"true\""
    )

    @Test
    fun `merged manifest ships no flagged security config`() {
        val manifest = javaClass.getResourceAsStream("/merged_manifest.xml")
            ?.readBytes()?.toString(Charsets.UTF_8)
            ?: return

        blockedFragments.forEach { fragment ->
            assertFalse(manifest.contains(fragment), "blocked flag: $fragment")
        }
    }
}

enum class Impact { AUTH_BYPASS, DATA_EXFILTRATION, DENIAL_OF_SERVICE, DISCLOSURE }

enum class Severity(val slaHours: Int) { CRITICAL(24), HIGH(72), MODERATE(240), LOW(720) }

fun triage(impact: Impact, needsRoot: Boolean): Severity = when {
    impact == Impact.AUTH_BYPASS && !needsRoot -> Severity.CRITICAL
    impact == Impact.DATA_EXFILTRATION -> Severity.HIGH
    needsRoot -> Severity.MODERATE
    else -> Severity.LOW
}

// The loop closes with a record, so the class of bug dies rather than this instance.
data class Advisory(val id: String, val severity: Severity, val fixedIn: String)

// commonMain
interface TokenStore {
    fun read(): String?
    fun write(token: String)
}

interface Clock {
    fun nowEpochMillis(): Long
}

class AuthSession(
    private val tokens: TokenStore,
    private val clock: Clock,
    private val issuedAtMillis: Long,
) {
    fun isExpired(ttlMillis: Long): Boolean =
        (clock.nowEpochMillis() - issuedAtMillis) > ttlMillis
}

// commonMain — the abstraction is an interface; consumers and tests see only this.
interface KeyStore {
    fun decrypt(alias: String, ciphertext: ByteArray): ByteArray
}

// androidMain — a plain implementation, chosen by the factory.
class AndroidKeystoreStore : KeyStore {
    override fun decrypt(alias: String, ciphertext: ByteArray): ByteArray {
        val key = getAndroidKeystoreKey(alias)
        val iv = ciphertext.copyOfRange(0, 12)
        val ct = ciphertext.copyOfRange(12, ciphertext.size)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.DECRYPT_MODE, key, GCMParameterSpec(128, iv))
        return cipher.doFinal(ct)
    }
}

// commonMain — one expect/actual seam, and only this one.
expect fun platformKeyStore(): KeyStore

// iosMain — the seam only; nothing else in shared code knows Keychain.
actual fun platformKeyStore(): KeyStore = KeychainStore()

// commonTest — a fake, because the interface is the dependency, not the actual.
class FakeKeyStore : KeyStore {
    override fun decrypt(alias: String, ciphertext: ByteArray): ByteArray =
        ciphertext.copyOf(8)   // test double, no real crypto
}
